import Vision
import CoreImage
import CoreGraphics
import CoreML

/// 512-dimensional deep neural face embedding generated by MobileFaceNet (ArcFace).
typealias FaceEmbedding = [Float]

protocol FaceEmbedding_Provider {
    /// Returns (embedding, faceBoundingBox, landmarks) for the primary
    /// (largest) face in the frame, or nil if no usable face is found.
    func embed(_ image: CIImage) -> (embedding: FaceEmbedding, box: CGRect, landmarks: VNFaceLandmarks2D?)?
}

/// Extracts 512-dimensional deep neural face embeddings using MobileFaceNet (ArcFace)
/// accelerated on the Apple Neural Engine.
final class VisionFaceEmbedder: FaceEmbedding_Provider {
    private var model: MLModel?
    private let ciContext = CIContext()
    private static let inputSize = CGSize(width: 112, height: 112)

    init() {
        loadModel()
    }

    private func loadModel() {
        let config = MLModelConfiguration()
        config.computeUnits = .all

        // 1. Look in main app bundle (.mlmodelc resource)
        if let bundleURL = Bundle.main.url(forResource: "FaceEmbedding", withExtension: "mlmodelc") {
            if let loaded = try? MLModel(contentsOf: bundleURL, configuration: config) {
                self.model = loaded
                return
            }
        }

        // 2. Look in local directory fallback
        let fallbackPath = "Lookt/ML/FaceEmbedding.mlmodelc"
        let fallbackURL = URL(fileURLWithPath: fallbackPath)
        if FileManager.default.fileExists(atPath: fallbackURL.path) {
            if let loaded = try? MLModel(contentsOf: fallbackURL, configuration: config) {
                self.model = loaded
                return
            }
        }
    }

    func embed(_ image: CIImage) -> (embedding: FaceEmbedding, box: CGRect, landmarks: VNFaceLandmarks2D?)? {
        let landmarksRequest = VNDetectFaceLandmarksRequest()
        let handler = VNImageRequestHandler(ciImage: image, options: [:])
        do {
            try handler.perform([landmarksRequest])
        } catch {
            return nil
        }

        guard let faces = landmarksRequest.results, !faces.isEmpty else {
            return nil
        }

        // Select the primary user face in frame (largest bounding box)
        let primary = faces.max(by: {
            $0.boundingBox.width * $0.boundingBox.height < $1.boundingBox.width * $1.boundingBox.height
        })!

        // Crop face region with 18% margin for facial context
        guard let croppedCG = cropFace(from: image, box: primary.boundingBox, padding: 0.18) else {
            return nil
        }

        // Generate 512-dimensional ArcFace embedding
        guard let embedding = generateEmbedding(from: croppedCG) else {
            return nil
        }

        return (embedding, primary.boundingBox, primary.landmarks)
    }

    private func cropFace(from image: CIImage, box: CGRect, padding: CGFloat) -> CGImage? {
        let w = image.extent.width
        let h = image.extent.height
        guard w > 20, h > 20 else { return nil }

        var rect = CGRect(
            x: box.origin.x * w,
            y: box.origin.y * h,
            width: box.width * w,
            height: box.height * h
        )
        let padX = rect.width * padding
        let padY = rect.height * padding
        rect = rect.insetBy(dx: -padX, dy: -padY).intersection(image.extent)
        guard !rect.isEmpty else { return nil }

        let croppedCI = image.cropped(to: rect)
        return ciContext.createCGImage(croppedCI, from: croppedCI.extent)
    }

    private func generateEmbedding(from faceImage: CGImage) -> [Float]? {
        guard let model = model else { return nil }
        guard let inputArray = imageToMultiArray(faceImage, targetSize: Self.inputSize) else { return nil }

        guard let inputProvider = try? MLDictionaryFeatureProvider(dictionary: [
            "face_image": MLFeatureValue(multiArray: inputArray)
        ]) else { return nil }

        guard let prediction = try? model.prediction(from: inputProvider) else { return nil }
        let feat = (prediction.featureValue(for: "embedding")?.multiArrayValue ??
                    prediction.featureValue(for: model.modelDescription.outputDescriptionsByName.keys.first ?? "")?.multiArrayValue)

        guard let multiArray = feat else { return nil }

        var out = [Float](repeating: 0, count: multiArray.count)
        for i in 0..<multiArray.count {
            out[i] = Float(truncating: multiArray[i])
        }

        // L2 normalize vector for cosine similarity
        let norm = sqrt(out.reduce(0) { $0 + $1 * $1 })
        guard norm > 0 else { return nil }
        return out.map { $0 / norm }
    }

    private func imageToMultiArray(_ image: CGImage, targetSize: CGSize) -> MLMultiArray? {
        let width = Int(targetSize.width)
        let height = Int(targetSize.height)
        let bytesPerPixel = 4
        let bytesPerRow = width * bytesPerPixel
        var pixelData = [UInt8](repeating: 0, count: height * bytesPerRow)

        guard let context = CGContext(
            data: &pixelData,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: bytesPerRow,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return nil }

        context.interpolationQuality = .high
        context.draw(image, in: CGRect(x: 0, y: 0, width: width, height: height))

        guard let array = try? MLMultiArray(shape: [1, 3, NSNumber(value: height), NSNumber(value: width)], dataType: .float32) else {
            return nil
        }

        for y in 0..<height {
            for x in 0..<width {
                let pixelIndex = y * bytesPerRow + x * bytesPerPixel
                let r = (Float(pixelData[pixelIndex]) - 127.5) / 127.5
                let g = (Float(pixelData[pixelIndex + 1]) - 127.5) / 127.5
                let b = (Float(pixelData[pixelIndex + 2]) - 127.5) / 127.5

                let spatial = y * width + x
                array[spatial] = NSNumber(value: r)
                array[width * height + spatial] = NSNumber(value: g)
                array[2 * width * height + spatial] = NSNumber(value: b)
            }
        }
        return array
    }
}

/// Cosine similarity between two unit-normalized face embeddings in [-1, 1].
/// For MobileFaceNet ArcFace embeddings:
/// - Same person (different angles / expressions / frames): >= 0.58 (typically 0.68 - 0.88)
/// - Different person / stranger: <= 0.35 (typically -0.05 to 0.28)
func cosineSimilarity(_ a: FaceEmbedding, _ b: FaceEmbedding) -> Float {
    guard a.count == b.count, !a.isEmpty else { return -1 }
    var dot: Float = 0
    for i in 0..<a.count {
        dot += a[i] * b[i]
    }
    return dot
}
